function addImdbRating(parent,title,year){const parsed=/^(.*?)\s*\((\d{4})\)$/.exec(title);if(parsed){title=parsed[1].trim();year=Number(parsed[2]);}const badge=document.createElement('span');badge.className='imdb-rating';badge.dataset.ratingTitle=title;badge.dataset.ratingYear=String(year||'');parent.append(badge);updateImdbBadge(badge);ratingObserver?.observe(badge)}
function updateImdbBadge(badge){const title=badge.dataset.ratingTitle,year=badge.dataset.ratingYear;let r=imdbRatings.get(title.toLowerCase()+'|'+year);if(!r&&!year){const matches=[...imdbRatings.values()].filter(x=>x.title.toLowerCase()===title.toLowerCase());if(matches.length===1)r=matches[0]}badge.hidden=false;badge.textContent=r?'IMDb '+r.rating.toFixed(1)+'/10':ratingsState==='loading'?'IMDb · Loading…':'IMDb · Unavailable';badge.classList.toggle('rating-unavailable',!r);badge.setAttribute('aria-label',title+(r?' IMDb rating '+r.rating+' out of 10':ratingsState==='loading'?' IMDb rating loading':' IMDb rating unavailable'));badge.title=r?'IMDb rating via OMDb':'No verified IMDb score is available yet';}
