function setSelectionMark(node,on,animate=false){node.replaceChildren();if(on){const svg=document.createElementNS('http://www.w3.org/2000/svg','svg');svg.setAttribute('viewBox','0 0 24 24');svg.setAttribute('aria-hidden','true');const path=document.createElementNS('http://www.w3.org/2000/svg','path');path.setAttribute('d','M5 12.5 9.5 17 19 7');svg.append(path);node.append(svg)}else node.textContent='+';node.classList.toggle('is-selected',on);if(animate){node.classList.remove('just-selected');void node.offsetWidth;node.classList.add('just-selected')}}
