const form=document.querySelector('#taste-form'),movies=document.querySelector('#movies'),picks=document.querySelector('#picks'),status=document.querySelector('#status'),filter=document.querySelector('#refinement');let active=[];let resultMode="sample";let activeDiscovery=null;let discoverySource='Qloo';
