function draw(){const rows=active.filter(m=>!libraryHas('watched',m)).filter(m=>filter.value!=='short'||Number.isFinite(m.minutes)&&m.minutes<120);picks.className='cards';picks.replaceChildren();document.querySelector('#count').textContent=`${rows.length} ${resultMode==="live"?discoverySource:"sample"} picks`;for(const [i,m] of rows.entries()){const article=document.createElement('article');article.className='card';const n=document.createElement('span');n.className='number';n.textContent=String(i+1).padStart(2,'0');n.setAttribute('aria-hidden','true');const body=document.createElement('div'),title=document.createElement('h3'),meta=document.createElement('div'),note=document.createElement('p'),badge=document.createElement('span');title.textContent=m.title;meta.className='meta';meta.textContent=[m.year,m.minutes?`${m.minutes} min`:null,m.genre].filter(Boolean).join(" / ");note.textContent=m.note;if(resultMode==='live'&&Array.isArray(m.reasons)){const heading=document.createElement('strong');heading.className='why-heading';heading.textContent='WHY IT FITS';const list=document.createElement('ul');list.className='match-reasons';for(const reason of m.reasons){const item=document.createElement('li');item.textContent=reason;list.append(item)}note.replaceChildren(heading,list);}badge.className='sample-label';badge.textContent=resultMode==='live'?(discoverySource==='Qloo'?'Qloo recommendation':'Verified '+discoverySource.toLowerCase()+' match'):'Curated example · not a Qloo match';body.append(title,meta,note,badge);addImdbRating(body,m.title,m.year);const poster=m.image?{image:m.image}:expandedCatalog.find(f=>f.kind==='movie'&&f.title.toLowerCase()===m.title.toLowerCase());if(poster){const img=document.createElement('img');img.className='result-poster';img.src=poster.image;img.alt=`${m.title} poster`;img.width=90;img.height=135;img.loading='lazy';img.referrerPolicy='no-referrer';img.addEventListener('error',()=>{img.hidden=true;article.classList.remove('has-poster')});article.classList.add('has-poster');article.append(img)}const actions=document.createElement('div');actions.className='film-actions';const save=document.createElement('button'),watched=document.createElement('button');save.type=watched.type='button';save.textContent=libraryHas('saved',m)?'Saved ✓':'Save for later';save.setAttribute('aria-pressed',String(libraryHas('saved',m)));save.addEventListener('click',()=>{const persisted=changeLibrary('saved',m);save.textContent=libraryHas('saved',m)?'Saved ✓':'Save for later';save.setAttribute('aria-pressed',String(libraryHas('saved',m)));renderFilmLibrary();libraryMessage(persisted?'Watchlist updated.':'Saved for this session; browser storage is unavailable.')});watched.textContent='Already watched';watched.addEventListener('click',()=>{const persisted=changeLibrary('watched',m);draw();renderFilmLibrary();libraryMessage(persisted?'Marked watched. Undo it in My films → Watched.':'Marked watched for this session; browser storage is unavailable.')});actions.append(save,watched);body.append(actions);article.append(n,body);picks.append(article)}if(!rows.length){const p=document.createElement('p');p.className='hint';p.textContent='No unwatched films fit these filters. Try fewer restrictions, or undo a watched film in My films.';picks.append(p)}}
