async function loadImdbRatings(){
 const storageKey='filmcompass-imdb-v1';try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved?.until>Date.now())for(const r of saved.ratings||[])if(typeof r.title==='string'&&Number.isFinite(r.rating)&&/^tt\d+$/.test(r.id))imdbRatings.set(r.title.toLowerCase()+'|'+r.year,r);}catch{}
 ratingsState='ready';document.querySelectorAll('.imdb-rating').forEach(updateImdbBadge);
 const queue=new Set(),requested=new Set();let timer,running=false;
 async function flush(){if(running)return;const titles=[...queue].slice(0,12);if(!titles.length)return;for(const t of titles){queue.delete(t);requested.add(t)}running=true;try{const response=await fetch('/api/ratings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({titles}),signal:AbortSignal.timeout(30000)});if(response.ok){const data=await response.json();for(const r of data.ratings||[])if(typeof r.title==='string'&&Number.isFinite(r.rating)&&/^tt\d+$/.test(r.id))imdbRatings.set(r.title.toLowerCase()+'|'+r.year,r);try{localStorage.setItem(storageKey,JSON.stringify({until:Date.now()+604800000,ratings:[...imdbRatings.values()]}))}catch{}if(data.available===false)queue.clear();}}catch{}finally{running=false;document.querySelectorAll('.imdb-rating').forEach(updateImdbBadge);if(queue.size)timer=setTimeout(flush,400);}}
 function enqueue(badge){const title=badge.dataset.ratingTitle,year=badge.dataset.ratingYear;if(!requested.has(title)&&!imdbRatings.has(title.toLowerCase()+'|'+year)){queue.add(title);clearTimeout(timer);timer=setTimeout(flush,400);}}
 if(typeof IntersectionObserver==='function'){ratingObserver=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting){enqueue(e.target);ratingObserver.unobserve(e.target)}},{rootMargin:'100px'});document.querySelectorAll('.imdb-rating').forEach(b=>ratingObserver.observe(b));}else document.querySelectorAll('.imdb-rating').forEach(enqueue);
}
if(typeof fetch==='function')loadImdbRatings();


