 aiState=data.state;selectionSignature=signature;input.value='';bubble(data.reply,'guide');if(data.choices)showMovieChoices(data.choices,title=>{const bare=title.replace(/ \(\d{4}\)$/,'');aiState.titles=aiState.titles.map(t=>t===bare?title:t);input.value='Use '+title+' and keep my other preferences.';aiForm.requestSubmit()});
